// The program the machine packages' array-wide tests (pet, c64) run under their
// emulators: arrays of 2-byte elements longer than 128, which the 6502
// backend used to index through an 8-bit doubled offset (the carry out of
// ASL was dropped, so element 185 landed on element 57). The program lights
// one screen cell (a reverse-video space) for every check that passes and
// leaves it blank for every one that fails, so a failure names the element.
// The cell is `screenBase + n`, the machine's text screen.
//
// packages/compiler/src/mos/lower/index.test.ts pins the emitted code in CI,
// where no emulator runs.

export const WIDE = 200; // usmallint elements: 400 bytes
export const BYTES = 256; // utinyint elements: the whole of Y's range

// The cell of each check, in screen order.
export const RING_AT = 0; // WIDE cells: ring[i] == i * 3, under a utinyint index
export const TABLE_AT = 200; // WIDE cells: a const table read under a utinyint index
export const BYTES_AT = 400; // BYTES cells: bytes[i] == i + 7 (mod 256), under a utinyint index
export const SPECIAL_AT = 656; // one cell per entry of SPECIAL
export const SPECIAL = [
  'constant store and read past element 127',
  'last element, constant index',
  'a usmallint index (store)',
  'a usmallint index (read)',
  'a neighbour of an element written by a constant index is untouched',
];

/** The source text, with the check cells in the screen at `screenBase` (0x8000 on a PET, 0x0400 on a C64). */
export function widePointerProbe(screenBase) {
  const table = Array.from({ length: WIDE }, (_, i) => i * 3).join(', ');
  const hex = `0x${screenBase.toString(16).toUpperCase().padStart(4, '0')}`;
  return `// generated by packages/compiler/test/fixtures/wide-array-probe.mjs
const TABLE: array<usmallint, ${WIDE}> = [${table}];
let ring: array<usmallint, ${WIDE}>;
let bytes: array<utinyint, ${BYTES}>;

function light(cell: usmallint): void {
    memory.write(${hex} + cell, 0xA0);
}

export function main(): void {
    for (let cell: usmallint = 0; cell < 1000; cell++) {
        memory.write(${hex} + cell, 0x20);
    }

    for (let i: utinyint = 0; i < ${WIDE}; i++) {
        let v: usmallint = i;
        ring[i] = v * 3;
    }
    for (let i: utinyint = 0; i < ${WIDE}; i++) {
        let want: usmallint = i;
        want = want * 3;
        let at: usmallint = i;
        if (ring[i] == want) {
            light(at + ${RING_AT});
        }
        if (TABLE[i] == want) {
            light(at + ${TABLE_AT});
        }
    }

    let b: utinyint = 0;
    while (true) {
        bytes[b] = b + 7;
        b = b + 1;
        if (b == 0) {
            break;
        }
    }
    b = 0;
    while (true) {
        let at: usmallint = b;
        if (bytes[b] == b + 7) {
            light(at + ${BYTES_AT});
        }
        b = b + 1;
        if (b == 0) {
            break;
        }
    }

    ring[150] = 777;
    ring[151] = 1;
    if (ring[150] == 777) {
        light(${SPECIAL_AT});
    }
    ring[${WIDE - 1}] = 4321;
    if (ring[${WIDE - 1}] == 4321) {
        light(${SPECIAL_AT + 1});
    }
    let far: usmallint = 190;
    ring[far] = 4242;
    if (ring[0] == 0) {
        light(${SPECIAL_AT + 2});
    }
    if (ring[far] == 4242) {
        light(${SPECIAL_AT + 3});
    }
    if (ring[151] == 1) {
        light(${SPECIAL_AT + 4});
    }
    while (true) {
        waitFrame();
    }
}
`;
}
